package pl.edu.pg.eti.kask.aquarium.user.dto;

import pl.edu.pg.eti.kask.aquarium.user.entity.Role;
import pl.edu.pg.eti.kask.aquarium.user.entity.User;

import java.time.LocalDate;
import java.util.UUID;

/**
 * JSON body of a registration request. The identifier is generated by the server and a new user is always
 * an ordinary user (role USER), nobody can register as an administrator.
 */
public record PostUserRequest(String login, String email, LocalDate birthDate, String password) {

    public User toEntity() {
        User user = new User(UUID.randomUUID(), login, email, birthDate, Role.USER);
        user.setPassword(password);
        return user;
    }
}
